it('uses actual controlled HTTP V2 envelopes, preserves order after lost receipt, and proves stale CAS is not an idempotent retry',async()=>{
 const origin='https://owner.example.test',credential='private-field-http';let current:typeof fieldDraft|undefined,writes=0,lose=true;
 const call=vi.fn(async(name:string,parameters:readonly unknown[])=>{expect(parameters.slice(0,3)).toEqual([U,T,F]);if(name==='get_paid_simple_draft'){if(!current)throw new FlowError('NOT_AVAILABLE');return current;}if(name!=='save_paid_customer_field_draft')throw Error('unexpected writer');const expected=parameters[4];if(expected!==(current?.revision??0))throw new FlowError('CONFLICT');current={schemaVersion:2,flowId:F,revision:Number(expected)+1,serviceId:parameters[3] as string,name:parameters[5] as string,presentation:{accentColor:parameters[6] as typeof fieldDraft.presentation.accentColor,layout:parameters[7] as typeof fieldDraft.presentation.layout},customerFields:parameters[8] as typeof fieldDraft.customerFields};writes++;return {schemaVersion:2,flowId:F,revision:current.revision};});
 const server=createFlowHttpServer({repository:{call},paidSimplePublication:true,ownerOrigins:[origin],customerOrigins:[],authenticateOwner:async token=>token===credential?U:null});await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address();if(!address||typeof address==='string')throw Error('missing loopback');const local='http://127.0.0.1:'+address.port;
 const calls=vi.fn<typeof fetch>(async(input,init)=>{const path=String(input);if(path.includes('/token?'))return json({access_token:credential});if(path.endsWith('/user'))return json({id:U});const response=await fetch(path.replace('https://api.example.test',local),{...init,headers:{...init?.headers,Origin:origin}});if(init?.method==='POST'&&lose){lose=false;await response.text();throw Error('lost field receipt');}return response;});
 try{const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},calls);await c.signIn('owner@example.test','fixture');await expect(c.savePaidSimpleCustomerFieldDraft(T,F,fieldDraftInput)).rejects.toMatchObject({delivery:'unknown'});expect(writes).toBe(1);await expect(c.savePaidSimpleCustomerFieldDraft(T,F,fieldDraftInput)).rejects.toMatchObject({delivery:'not_sent'});expect(calls).toHaveBeenCalledTimes(3);expect(await c.loadPaidSimpleDraft(T,F)).toEqual(fieldDraft);expect(calls.mock.calls[3]?.[1]?.method).toBe('GET');expect(writes).toBe(1);const stale=await fetch(local+'/api/paid-simple-flows/'+F+'/draft?tenantId='+T,{method:'POST',headers:{Origin:origin,Authorization:'Bearer '+credential,'Content-Type':'application/json'},body:JSON.stringify(fieldDraftInput)});expect(stale.status).toBe(409);expect(await stale.json()).toEqual({ok:false,code:'CONFLICT'});expect(writes).toBe(1);}finally{await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
});
