it.each([false,true])('uses real initializer HTTP handler and replays only identical operation after lost receipt=%s',async loseReceipt=>{
 const origin='https://portal.example.test',ownerToken='synthetic-existing-business-owner';let stored:{body:string;profile:ReturnType<typeof BusinessProfileSchema.parse>}|undefined,writes=0,drop=loseReceipt;
 const initializer=vi.fn(async(actor:string,tenantId:string,input:BusinessProfileInitializationInput)=>{if(actor!==U||tenantId!==T)throw new FlowError('FORBIDDEN');const body=JSON.stringify(input);if(stored&&stored.body!==body)throw new FlowError('CONFLICT');if(!stored){writes++;stored={body,profile:BusinessProfileSchema.parse(initializedReceipt)};}return stored.profile;});
 const server=createFlowHttpServer({repository:{call:vi.fn()},businessOnboarding:true,businessProfileInitialize:initializer,businessProfile:async(actor,tenantId)=>{if(actor!==U||tenantId!==T)throw new FlowError('FORBIDDEN');if(!stored)throw new FlowError('NOT_AVAILABLE');return stored.profile;},ownerOrigins:[origin],customerOrigins:[],authenticateOwner:async token=>token===ownerToken?U:null});await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));
 try{const address=server.address() as {port:number};const f=vi.fn<typeof fetch>(async(input,options)=>{const url=new URL(String(input));if(url.pathname==='/auth/v1/token')return json({access_token:ownerToken});if(url.pathname==='/auth/v1/user')return json({id:U});if(url.pathname==='/rest/v1/tenant_members')return json(ownerMemberships);const response=await fetch('http://127.0.0.1:'+address.port+url.pathname+url.search,{...options,headers:{...options?.headers,Origin:origin}});if(url.pathname==='/api/business-profile/initialize'&&response.ok&&drop){drop=false;await response.text();throw Error('Lost committed initializer HTTP receipt');}return response;});const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');if(loseReceipt){await expect(c.initializeBusinessProfile(T,initializeInput)).rejects.toMatchObject({delivery:'unknown'});expect(await c.businessProfile(T)).toMatchObject({status:'initialized'});expect(c.businessProfileInitializationState(T)).toMatchObject({phase:'unknown'});}expect(await c.initializeBusinessProfile(T,initializeInput)).toEqual(initializedReceipt);expect(writes).toBe(1);expect(initializer).toHaveBeenLastCalledWith(U,T,initializeInput);const posts=f.mock.calls.filter(([url])=>String(url).includes('/api/business-profile/initialize?'));expect(posts).toHaveLength(loseReceipt?2:1);if(loseReceipt)expect(posts[0]?.[1]?.body).toBe(posts[1]?.[1]?.body);
 }finally{server.closeAllConnections();await new Promise<void>((resolve,reject)=>server.close(error=>error?reject(error):resolve()));}
},15000);
