it('actual owner read HTTP uses verified bearer and owner origin without calling customer reader or any writer',async()=>{const owner='https://portal.example.test',checkout='https://checkout.example.test',credential='owner-token-123456';const call=vi.fn(async(name:string,params:readonly unknown[])=>{expect(name).toBe('get_paid_journey_owner_publication');expect(params).toEqual([U,T,journeyFlow]);return ownerJourneyPublication;});const server=createFlowHttpServer({repository:{call},paidJourneyPublication:true,ownerOrigins:[owner],customerOrigins:[checkout],authenticateOwner:async token=>token===credential?U:null});await new Promise<void>(r=>server.listen(0,'127.0.0.1',r));const address=server.address();if(!address||typeof address==='string')throw Error('loopback missing');const f=vi.fn<typeof fetch>(async(url,init)=>{if(String(url).startsWith(config.url))return new URL(String(url)).pathname.includes('/token')?json({access_token:credential}):json({id:U});return fetch('http://127.0.0.1:'+address.port+new URL(String(url)).pathname+new URL(String(url)).search,{...init,headers:{...init?.headers,Origin:owner}});});try{const c=createRuntimeClient({...config,bookingApiOrigin:'https://api.example.test'},f);await c.signIn('owner@example.test','fixture');expect(await c.readPaidJourneyOwnerPublication(T,journeyFlow)).toEqual(ownerJourneyPublication);expect(call).toHaveBeenCalledTimes(1);expect(f.mock.calls.at(-1)?.[1]?.method).toBe('GET');expect(f.mock.calls.at(-1)?.[1]?.headers).toEqual({Authorization:'Bearer '+credential});expect(c.paidJourneyPublicationState(T)).toEqual({phase:'ready'});}finally{server.closeAllConnections();await new Promise<void>(r=>server.close(()=>r()));}});

